def normalize_quotes(apps, schema_editor):
    Quote = apps.get_model('portal', 'JobQuotation')
    for quote in Quote.objects.all().iterator():
        Quote.objects.filter(pk=quote.pk).update(
            series_id=uuid.uuid4(), subtotal=quote.amount,
            status='sent' if quote.status == 'pending' else quote.status,
            sent_at=quote.created_at,
        )


